function loadDB(){try{let d=JSON.parse(localStorage.getItem(STORAGE_KEY));if(d&&d.orders&&d.inventory)return d}catch(e){}return structuredClone(SEED)}
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(db));render()}
function esc(s=''){return String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}
function fmtDate(d,opts={day:'numeric',month:'short'}){if(!d)return '—';return new Date(d+'T12:00:00').toLocaleDateString('en-IN',opts)}
function fmtTime(s){return new Date(s).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}
function daysLeft(d){return Math.ceil((new Date(d+'T23:59:59')-new Date())/86400000)}
function isLate(o){return !['Completed','Dispatched'].includes(o.stage)&&daysLeft(o.deadline)<0}
function progress(o){let total=o.processes.reduce((a,p)=>a+p.completed,0),target=o.qty*o.processes.length;return target?Math.round(total/target*100):0}
function materialStock(m){let x=db.inventory.find(i=>i.name===m);return x?x.opening+x.incoming+x.adjustments-x.reserved-x.consumed-x.wastage:0}
function currentActor(){return db.role==='Admin'?'Shubham Jain':(window.staffMember||'Amit Shah')}
function addActivity(actor,entity,text){let time=new Date().toISOString();db.activity.unshift({time,actor,entity,text});let order=db.orders.find(o=>o.id===entity);if(!order&&typeof getJobs==='function')order=getJobs().find(j=>j.id===entity)?.o;if(order&&actor!=='System'){order.updatedBy=actor;order.updatedAt=time}}
function toast(message){let w=document.createElement('div');w.className='toast';w.textContent=message;let root=document.querySelector('#toast-region');root.appendChild(w);setTimeout(()=>w.remove(),3000)}
function chip(text){let t=String(text||'');let c=['Completed','Ready for dispatch','Dispatched','In production','On time'].includes(t)?'green':['Being prepared','Quality check','On hold','At risk'].includes(t)?'amber':['Delayed','Overdue','Cancelled'].includes(t)?'red':['Order received'].includes(t)?'blue':'gray';return `<span class="status ${c}">${esc(t)}</span>`}
function header(kicker,title,sub,button=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div>${button}</div>`}
function button(text,action,cls='primary-button',icon=''){return `<button class="${cls}" data-action="${action}">${icon?`<span>${icon}</span>`:''}${text}</button>`}
function sortedOrders(){return [...db.orders].sort((a,b)=>a.deadline.localeCompare(b.deadline))}
function activeOrders(){return db.orders.filter(o=>!['Completed','Cancelled'].includes(o.stage))}
function alerts(){let arr=[];activeOrders().forEach(o=>{if(isLate(o))arr.push({tone:'red',icon:'!',title:`${o.id} is overdue`,detail:`${o.client} · due ${fmtDate(o.deadline)}`,time:`${Math.abs(daysLeft(o.deadline))}d late`});else if(daysLeft(o.deadline)<=2)arr.push({tone:'',icon:'◷',title:`${o.id} deadline approaching`,detail:`${o.client} · ${daysLeft(o.deadline)===0?'Due today':`Due in ${daysLeft(o.deadline)} days`}`,time:'Action needed'});});db.inventory.forEach(m=>{let s=materialStock(m.name);if(s<m.reorder)arr.push({tone:'',icon:'▧',title:`${m.name} stock is running low`,detail:`${Math.max(0,s)} ${m.unit} available · reorder at ${m.reorder}`,time:'Inventory'});});return arr}
function renderGuide(){return `${header('HELP CENTER','Operations guide','A practical walkthrough for managing orders from intake through delivery.')}<div class="guide-grid"><section class="panel guide-card"><div class="eyebrow">ADMIN · ORDER LIFECYCLE</div><h2>Run an order from start to finish</h2><ol class="guide-steps"><li><strong>Create the order</strong><p>Open <a href="#orders">Orders</a> and choose New order. Add the client, product, quantity, dates, materials, and notes. Add a clear product photo so the team can identify its design and finish.</p></li><li><strong>Plan production</strong><p>Use <a href="#production">Master production</a> to review the schedule and <a href="#jobs">Job sheets</a> to assign Iron, Rope, and Fabric work to staff with due dates.</p></li><li><strong>Record progress and QC</strong><p>Staff update completed units, materials used, and notes on their job sheets. Record each stage inspection in the QC checkpoints. Resolve a failed check before moving work forward.</p></li><li><strong>Check materials</strong><p>Review <a href="#inventory">Inventory</a> for available stock and transactions. Log incoming stock, consumption, adjustments, or wastage so balances stay traceable.</p></li><li><strong>Dispatch and report</strong><p>When production and QC are complete, move the order to ready for dispatch. Record carrier and tracking details in <a href="#dispatch">Dispatch</a>; use <a href="#reports">Reports</a> and <a href="#activity">Activity log</a> to review outcomes and accountability.</p></li></ol></section><section class="panel guide-card"><div class="eyebrow">STAFF · YOUR WORK</div><h2>Update your assigned jobs</h2><ol class="guide-steps"><li><strong>Switch to Staff view</strong><p>Use the profile menu at the bottom of the sidebar and choose Staff view. Your dashboard focuses on assigned production work.</p></li><li><strong>Open the job sheet</strong><p>Choose a job to see the order, product, quantity, due date, materials, notes, and current QC checkpoints.</p></li><li><strong>Add a product photo</strong><p>On the order or job details, use the product photo upload control to attach a reference image. A clear photo helps everyone confirm the product, colour, and finish.</p></li><li><strong>Update progress accurately</strong><p>Record completed units, material consumption, and useful notes. Your staff identity is recorded with updates so the admin can trace who changed each detail.</p></li><li><strong>Complete QC at every stage</strong><p>Mark the inspection after each relevant process, such as framework fabrication, powder coating, rope work, or fabric work. Include notes for issues that need correction.</p></li></ol><div class="guide-callout"><strong>Need a specific screen?</strong><p>Use these shortcuts to open your workspace:</p><div class="guide-links"><a href="#orders">Orders →</a><a href="#jobs">Job sheets →</a><a href="#inventory">Inventory →</a></div></div></section><section class="panel guide-card guide-note"><div class="eyebrow">WORKSPACE DATA</div><h2>Where updates are saved</h2><p>This demo currently saves changes in the browser’s local storage. Data entered here is available in this browser and device; it does not yet sync across users or devices.</p><a href="#settings">Open settings →</a></section></div>`}
function render(){document.querySelectorAll('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===page));document.querySelector('#breadcrumb').textContent=({dashboard:'Dashboard',orders:'Orders',production:'Master production',jobs:'Job sheets',inventory:'Inventory',dispatch:'Dispatch',reports:'Reports',staff:'Staff',activity:'Activity log',settings:'Settings',guide:'Operations guide'})[page]||'Dashboard';document.querySelector('#nav-order-count').textContent=activeOrders().length;document.querySelector('#role-label').textContent=db.role==='Admin'?'Administrator':'Production staff';document.querySelector('#today-date').textContent=new Date().toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'});let root=document.querySelector('#page-content');let map={dashboard:renderDashboard,orders:renderOrders,production:renderProduction,jobs:renderJobs,inventory:renderInventory,dispatch:renderDispatch,reports:renderReports,staff:renderStaff,activity:renderActivity,settings:renderSettings,guide:renderGuide};root.innerHTML=(map[page]||renderDashboard)();}
function renderDashboard(){if(db.role==='Staff')return renderStaffDashboard();let active=activeOrders(),inPrep=active.filter(o=>['Order received','Being prepared','Ready for production'].includes(o.stage)).length,prod=active.filter(o=>o.stage==='In production').length,ready=active.filter(o=>['Ready for dispatch','Dispatched'].includes(o.stage)).length,late=active.filter(isLate).length,shorts=db.inventory.filter(m=>materialStock(m.name)<m.reorder).length,due=active.filter(o=>daysLeft(o.deadline)<=0).length;let stages=['Order received','Being prepared','In production','Quality check','Ready for dispatch','Dispatched'];let stageCounts=stages.map(s=>db.orders.filter(o=>o.stage===s).length);let orders=sortedOrders().filter(o=>o.stage!=='Completed').slice(0,5);let attention=alerts().slice(0,4);let cards=[['ACTIVE ORDERS',active.length,'Across all active stages','▤'],['IN PRODUCTION',prod,'Orders on the floor','◉'],['READY TO DISPATCH',ready,'Awaiting carrier handoff','↗'],['NEEDS ATTENTION',late+shorts+due,`${late} overdue · ${shorts} stock alerts`,'!']];return `${header('THURSDAY, 8 OCTOBER 2026','Good morning, Umami','Here’s what’s moving across the studio today.',button('New order','new-order','primary-button','＋'))}<section class="kpi-grid">${cards.map(c=>`<article class="kpi-card"><div class="kpi-top"><span>${c[0]}</span><span class="kpi-icon">${c[3]}</span></div><div class="kpi-value">${c[1]}</div><div class="kpi-foot">${c[2]}</div></article>`).join('')}</section><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2>Order pipeline</h2><p>Live view of every order in motion</p></div><a class="panel-link" href="#orders">All orders ↗</a></div><div class="pipeline">${stages.map((s,i)=>`<div class="pipeline-step" data-stage="${s}"><div class="pipeline-dot">${i+1}</div><div class="pipeline-count">${stageCounts[i]}</div><div class="pipeline-label">${s}</div></div>`).join('')}</div><div class="panel-header"><h2>Orders needing attention</h2><a class="panel-link" href="#orders">View all →</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ORDER</th><th>CLIENT</th><th>STAGE</th><th>DEADLINE</th><th>PROGRESS</th></tr></thead><tbody>${orders.length?orders.map(orderRow).join(''):`<tr><td colspan="5" class="empty-state">All clear. No active orders.</td></tr>`}</tbody></table></div></section><section class="panel"><div class="panel-header"><div><h2>Attention needed</h2><p>Deadlines and material alerts</p></div><span class="status ${attention.length?'amber':'green'}">${attention.length} alerts</span></div><div class="attention-list">${attention.length?attention.map(a=>`<div class="attention-item"><span class="attention-icon ${a.tone}">${a.icon}</span><div><strong>${esc(a.title)}</strong><p>${esc(a.detail)}</p></div><span class="attention-time">${esc(a.time)}</span></div>`).join(''):`<div class="empty-state">No urgent items right now.</div>`}</div><div class="panel-header" style="margin-top:18px"><div><h2>Stock at a glance</h2><p>Available after reservations</p></div><a class="panel-link" href="#inventory">Inventory →</a></div>${db.inventory.map(m=>{let avail=materialStock(m.name),used=m.opening+m.incoming+m.adjustments||1;return `<div class="material-row"><div><strong>${m.name}</strong><small>${m.reserved} ${m.unit} reserved · ${m.consumed} ${m.unit} used</small></div><span class="qty">${avail} ${m.unit}</span><div class="bar"><span style="width:${Math.max(3,Math.min(100,avail/used*100))}%;background:${avail<m.reorder?'#d78370':''}"></span></div></div>`}).join('')}</section></div><div class="lower-grid"><section class="panel"><div class="panel-header"><div><h2>Production pulse</h2><p>Work in progress across all orders</p></div><a class="panel-link" href="#jobs">Open job sheets →</a></div>${PROCESSES.map(p=>{let list=active.flatMap(o=>o.processes.filter(x=>x.name===p));let done=list.filter(x=>x.status==='Completed').length,pct=list.length?Math.round(done/list.length*100):0;return `<div class="material-row"><div><strong>${p}</strong><small>${list.length-done} active jobs · ${done} completed</small></div><span class="qty">${pct}%</span><div class="bar"><span style="width:${pct}%"></span></div></div>`}).join('')}</section><section class="panel"><div class="panel-header"><div><h2>Recent activity</h2><p>Latest updates from the floor</p></div><a class="panel-link" href="#activity">Activity log →</a></div>${renderTimeline(db.activity.slice(0,4))}</section></div>`}
function orderRow(o){let d=daysLeft(o.deadline),dateRisk=d<0?'risk':d<=2?'risk':'';return `<tr data-order="${o.id}"><td class="id-cell">${o.id}</td><td class="client-cell"><strong>${esc(o.client)}</strong><small>${esc(o.product)}</small></td><td>${chip(o.stage)}</td><td class="${dateRisk}">${fmtDate(o.deadline)}${d<0?` · ${Math.abs(d)}d late`:''}</td><td class="progress-cell"><div class="progress-label"><span>${progress(o)}%</span><span>${o.qty} units</span></div><div class="progress-track"><span style="width:${progress(o)}%"></span></div></td></tr>`}
function renderOrders(){let selected=orderFilter;let list=sortedOrders().filter(o=>(selected==='All'||(selected==='Delayed'?isLate(o):o.stage===selected)));if(db.role==='Staff')list=list.filter(o=>o.processes.some(p=>p.assigned===(window.staffMember||'Amit Shah')));return `${header('OPERATIONS','Orders','Manage the full order lifecycle from intake through completion.',button('New order','new-order','primary-button','＋'))}<div class="tabs">${['All','Order received','Being prepared','In production','Quality check','Ready for dispatch','Dispatched','Completed','Delayed'].map(s=>`<button class="tab ${selected===s?'active':''}" data-order-filter="${s}">${s} <span style="color:#9da69f">${s==='All'?db.orders.length:s==='Delayed'?db.orders.filter(isLate).length:db.orders.filter(o=>o.stage===s).length}</span></button>`).join('')}</div><div class="toolbar"><select id="order-priority"><option value="All">All priorities</option><option>Urgent</option><option>High</option><option>Standard</option></select><select id="order-deadline"><option value="All">Any deadline</option><option value="soon">Due in 3 days</option><option value="late">Overdue</option></select><span class="spacer"></span><span class="eyebrow">${list.length} ORDERS</span></div><section class="panel table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>ORDER</th><th>CLIENT / PRODUCT</th><th>QUANTITY</th><th>STAGE</th><th>PRIORITY</th><th>DEADLINE</th><th>PROGRESS</th></tr></thead><tbody>${list.length?list.map(o=>`<tr data-order="${o.id}"><td class="id-cell">${o.id}</td><td class="client-cell"><strong>${esc(o.client)}</strong><small>${esc(o.product)}</small></td><td>${o.qty} units</td><td>${chip(o.stage)}</td><td>${o.priority==='Urgent'?chip('Overdue'):o.priority}</td><td class="${isLate(o)?'risk':''}">${fmtDate(o.deadline)} ${isLate(o)?'· late':''}</td><td class="progress-cell"><div class="progress-label"><span>${progress(o)}%</span></div><div class="progress-track"><span style="width:${progress(o)}%"></span></div></td></tr>`).join(''):`<tr><td colspan="7" class="empty-state">No orders in this stage.</td></tr>`}</tbody></table></div></section>`}
function renderProduction(){const cols=[['orderDate','ORDER DATE'],['commencement','COMMENCEMENT'],['orderNo','ORDER NO.'],['client','CLIENT'],['sku','SKU'],['product','PRODUCT'],['qty','QTY'],['deadline','DEADLINE'],['fabricRequired','FABRIC REQUIRED'],['fabricStatus','FABRIC STATUS'],['ropeRequired','ROPE REQUIRED'],['ropeStatus','ROPE STATUS'],['foamRequired','FOAM REQUIRED'],['foamStatus','FOAM STATUS'],['tileRequired','TILE / STONE REQUIRED'],['tileStatus','TILE / STONE STATUS'],['metalRequired','METAL REQUIRED'],['metalStatus','METAL STATUS'],['structureStatus','STRUCTURE STATUS'],['structureQca','STRUCTURE QCA'],['powderStatus','POWDER COATING STATUS'],['powderQca','POWDER COATING QCA'],['weavingStatus','WEAVING STATUS'],['weavingQca','WEAVING QCA'],['upholsteryStatus','UPHOLSTERY STATUS'],['upholsteryQca','UPHOLSTERY QCA'],['tileProductionStatus','TILE / STONE STATUS'],['currentStatus','CURRENT STATUS'],['procurementDelay','PROCUREMENT DELAY'],['deadlineDelay','DEADLINE DELAY'],['rework','REWORK ALERT'],['notes','NOTES'],['completion','COMPLETION %']];let q=(document.querySelector('#tracker-search')?.value||'').toLowerCase();let list=trackerRows.filter(r=>!q||[r.orderNo,r.client,r.sku,r.product,r.currentStatus].join(' ').toLowerCase().includes(q));let editable=new Set(['fabricStatus','ropeStatus','foamStatus','tileStatus','metalStatus','structureStatus','structureQca','powderStatus','powderQca','weavingStatus','weavingQca','upholsteryStatus','upholsteryQca','tileProductionStatus','currentStatus','procurementDelay','deadlineDelay','rework']);let options={fabricStatus:['Pending','Received','Not Required'],ropeStatus:['Pending','Received','Not Required'],foamStatus:['Pending','Received','Not Required','ALUMINIUM'],tileStatus:['Pending','Received','Not Required'],metalStatus:['Pending','Received','Not Required'],structureStatus:['Not Started','In Progress','Done','Not Required'],structureQca:['Pending','Approved','Rejected','Not Required'],powderStatus:['Not Started','In Progress','Done','Not Required'],powderQca:['Pending','Approved','Rejected','Not Required'],weavingStatus:['Not Started','In Progress','Done','Not Required'],weavingQca:['Pending','Approved','Rejected','Not Required'],upholsteryStatus:['Not Started','In Progress','Done','Not Required'],upholsteryQca:['Pending','Approved','Rejected','Not Required'],tileProductionStatus:['Pending','Received','Not Required','In Progress','Done'],currentStatus:['Waiting for Material','In Assembly','In Production','In Weaving','In Painting','Quality Check','Ready for Dispatch','Completed'],procurementDelay:['On Track','Material Order Delay'],deadlineDelay:['On Track','Late'],rework:['','Required','Resolved']};let cell=(r,key,i)=>{let value=r[key]??'';if(key==='completion')return `<span class="tracker-percent">${Number(value)||0}%</span><div class="tracker-progress"><i style="width:${Math.max(0,Math.min(100,Number(value)||0))}%"></i></div>`;if(editable.has(key)){let opts=options[key]||[];return `<button type="button" class="tracker-select ${/Pending|Late|Delay/.test(value)?'warning':/Done|Received|Approved|Completed/.test(value)?'good':''}" data-tracker-index="${trackerRows.indexOf(r)}" data-tracker-key="${key}" data-tracker-options="${esc([...new Set([value,...opts])].join('|'))}" aria-label="${cols.find(c=>c[0]===key)[1]}: ${esc(value||'—')} for ${esc(r.orderNo)} ${esc(r.sku)}" aria-haspopup="listbox" aria-expanded="false">${esc(value||'—')}<span class="tracker-caret" aria-hidden="true">⌄</span></button>`}return esc(value||'—')};return `${header('OPERATIONS','Master production','Order master and production tracker · update material, stage and QC status in place.',button('Update a job','jobs','secondary-button','＋'))}<div class="tracker-toolbar"><div><strong>${list.length}</strong> product lines across <strong>${new Set(list.map(r=>r.orderNo)).size}</strong> orders</div><input id="tracker-search" type="search" placeholder="Search order, client or SKU…" value="${esc(document.querySelector('#tracker-search')?.value||'')}" aria-label="Search production tracker"></div><section class="panel table-panel tracker-panel"><div class="tracker-scroll"><table class="data-table tracker-table"><thead><tr>${cols.map(([k,label])=>`<th>${label}</th>`).join('')}</tr></thead><tbody>${list.map((r,i)=>`<tr class="${i%2?'':'tracker-highlight'}">${cols.map(([key])=>`<td>${cell(r,key,i)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><div class="info-banner tracker-info">Status and QC updates save automatically in this browser. Use the horizontal scroll bar to review all tracker columns. Completion is entered as a percentage.</div>`}
function jobProgress(p,q){let n=Math.round(p.completed/q*100);return `<span style="color:${n===100?'var(--green)':'#66736a'};font-size:12px;font-weight:700">${n}%</span>`}
function jobId(o,p){return `JOB-${o.id.slice(3)}-${p.name.startsWith('Iron')?'IRN':p.name.startsWith('Rope')?'ROP':'FAB'}`}
function getJobs(){return db.orders.flatMap(o=>o.processes.map(p=>({o,p,id:jobId(o,p)})))}
function renderJobs(){let jobs=getJobs().filter(({o,p})=>{let q=jobFilters.query.toLowerCase();return (jobFilters.process==='All'||p.name===jobFilters.process)&&(jobFilters.status==='All'||p.status===jobFilters.status)&&(jobFilters.staff==='All'||p.assigned===jobFilters.staff)&&(!q||`${o.id} ${o.client} ${o.product} ${p.name} ${p.assigned}`.toLowerCase().includes(q))});let columns=['Not started','In progress','On hold','Completed','Delayed'];return `${header('OPERATIONS','Job sheets','Process-level workspaces for Iron, Rope and Fabric production.',button('Update job','update-job','primary-button','＋'))}<div class="toolbar"><input class="filter-search" id="job-search" placeholder="Search job, order or staff" value="${esc(jobFilters.query)}"><select id="job-process"><option>All</option>${PROCESSES.map(p=>`<option ${jobFilters.process===p?'selected':''}>${p}</option>`).join('')}</select><select id="job-status"><option>All</option>${columns.map(s=>`<option ${jobFilters.status===s?'selected':''}>${s}</option>`).join('')}</select><select id="job-staff"><option>All</option>${PEOPLE.map(s=>`<option ${jobFilters.staff===s?'selected':''}>${s}</option>`).join('')}</select><span class="spacer"></span><span class="eyebrow">${jobs.length} JOBS</span></div><div class="kanban">${columns.map(col=>{let list=jobs.filter(j=>j.p.status.toLowerCase()===col.toLowerCase());return `<section class="kanban-column"><div class="kanban-title">${col}<span>${list.length}</span></div>${list.map(({o,p,id})=>`<article class="job-card" data-job="${id}"><div class="job-card-id">${id} · ${o.id}</div><h3>${p.name}</h3><p>${esc(o.client)} · ${esc(o.product)}</p><div class="job-card-footer"><span>${esc(p.assigned)}</span><span>${fmtDate(p.due)}</span></div><div class="progress-label" style="margin-top:9px"><span>${p.completed} / ${o.qty} units</span><span>${jobProgress(p,o.qty)}</span></div><div class="progress-track"><span style="width:${Math.min(100,p.completed/o.qty*100)}%"></span></div></article>`).join('')||`<div class="empty-state">No jobs</div>`}</section>`}).join('')}</div>`}
function renderInventory(){let demoMaterials=db.inventory.filter(m=>m.name!=='Rope'),demoTransactions=db.transactions.filter(t=>t.material!=='Rope');return `${header('OPERATIONS','Inventory','Rope inventory from the stock workbook, alongside the workspace material ledger.',button('Record transaction','new-transaction','primary-button','＋'))}${renderRopeInventory()}<div class="eyebrow inventory-subhead">OTHER WORKSPACE MATERIALS</div><div class="stock-grid">${demoMaterials.map(m=>{let available=materialStock(m.name),total=m.opening+m.incoming+m.adjustments;return `<section class="stock-card"><div class="stock-card-top"><div><h2>${m.name}</h2><p>Workspace material · measured in ${m.unit}</p></div>${chip(available<m.reorder?'Low stock':'In stock')}</div><div class="stock-number ${available<m.reorder?'risk':''}">${available}<span class="stock-unit"> ${m.unit} available</span></div><div class="progress-track"><span style="width:${Math.max(0,Math.min(100,available/Math.max(total,1)*100))}%;background:${available<m.reorder?'#c26b5c':''}"></span></div><div class="stock-details"><div><small>ON HAND</small><strong>${total-m.consumed-m.wastage} ${m.unit}</strong></div><div><small>RESERVED</small><strong>${m.reserved} ${m.unit}</strong></div><div><small>CONSUMED</small><strong>${m.consumed} ${m.unit}</strong></div><div><small>REORDER AT</small><strong>${m.reorder} ${m.unit}</strong></div></div></section>`}).join('')}</div><section class="panel table-panel inventory-ledger"><div class="panel-header"><div><h2>Workspace transactions</h2><p>Transactions entered in this browser workspace.</p></div><span class="eyebrow">${demoTransactions.length} RECORDS</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>TRANSACTION</th><th>MATERIAL</th><th>TYPE</th><th>QUANTITY</th><th>ORDER / JOB</th><th>STAFF</th><th>DATE</th><th>NOTES</th></tr></thead><tbody>${demoTransactions.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td class="id-cell">${t.id}</td><td>${t.material}</td><td>${chip(t.type)}</td><td>${t.type==='Consumption'||t.type==='Wastage'?'-':''}${t.qty} ${db.inventory.find(m=>m.name===t.material)?.unit}</td><td>${t.order}<small style="display:block;color:#9ca49f;margin-top:3px">${t.job}</small></td><td>${esc(t.staff)}</td><td>${fmtDate(t.date)}</td><td>${esc(t.notes)}</td></tr>`).join('')}</tbody></table></div></section>`}
function renderRopeInventory(){if(!ropeSheetData)return `<section class="panel rope-sheet"><div class="panel-header"><div><h2>Rope inventory</h2><p>Loading rope stock workbook…</p></div></div></section>`;let tabs=[['stock_master','Stock Master'],['outward_log','Outward Log'],['purchase_log','Purchase Log']],rows=ropeSheetData[ropeInventoryTab]||[],needle=ropeInventorySearch.toLowerCase();let filtered=rows.filter(r=>Object.values(r).join(' ').toLowerCase().includes(needle));let number=v=>{let n=parseFloat(String(v??'').replace(/,/g,''));return Number.isFinite(n)?n:0};let stock=ropeSheetData.stock_master||[],totals=stock.reduce((a,r)=>{let opening=number(r['Opening Stock (m)']),purchase=number(r['Total Purchased (m)']),out=number(r['Total Outward (m)']),current=r['Current Balance (m)']===''?opening+purchase-out:number(r['Current Balance (m)']);a.opening+=opening;a.purchased+=purchase;a.outward+=out;a.current+=current;if(current<100)a.low++;return a},{opening:0,purchased:0,outward:0,current:0,low:0});let columns=rows.length?Object.keys(rows[0]).filter(k=>k):[];let display=(r,k)=>{if(ropeInventoryTab==='stock_master'&&k==='Current Balance (m)'&&!r[k])return String(number(r['Opening Stock (m)'])+number(r['Total Purchased (m)'])-number(r['Total Outward (m)']));return r[k]||'—'};return `<section class="panel rope-sheet"><div class="rope-sheet-title"><div><div class="eyebrow">IMPORTED ROPE WORKBOOK</div><h2>Rope inventory</h2><p>Stock by rope type, thickness and colour, with purchase and issue history.</p></div><a class="rope-source" href="https://docs.google.com/spreadsheets/d/1hcbro2PoPJFZ3b9AKla_ZG0vR66Ek9mY/edit" target="_blank" rel="noopener">Open source sheet ↗</a></div><div class="rope-kpis"><div><small>ON HAND</small><strong>${Math.round(totals.current).toLocaleString('en-IN')} m</strong></div><div><small>OPENING STOCK</small><strong>${Math.round(totals.opening).toLocaleString('en-IN')} m</strong></div><div><small>PURCHASED</small><strong>${Math.round(totals.purchased).toLocaleString('en-IN')} m</strong></div><div><small>ISSUED OUT</small><strong>${Math.round(totals.outward).toLocaleString('en-IN')} m</strong></div><div class="rope-kpi-alert"><small>LOW / ZERO BALANCE (&lt;100 m)</small><strong>${totals.low} SKUs</strong></div></div><div class="rope-sheet-controls"><div class="rope-tabs">${tabs.map(([id,label])=>`<button type="button" data-rope-tab="${id}" class="${ropeInventoryTab===id?'active':''}">${label}<span>${(ropeSheetData[id]||[]).length}</span></button>`).join('')}</div><input id="rope-inventory-search" type="search" placeholder="Search type, size, colour, or job…" value="${esc(ropeInventorySearch)}" aria-label="Search rope inventory"></div><div class="rope-data-scroll"><table class="data-table rope-data-table"><thead><tr>${columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${filtered.map(r=>`<tr>${columns.map(c=>`<td>${esc(display(r,c))}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${columns.length}" class="empty-state">No matching rope records.</td></tr>`}</tbody></table></div><div class="rope-sheet-foot">Showing ${filtered.length} of ${rows.length} rows · workbook snapshot imported from Google Sheets · quantities are in metres.</div></section>`}
function renderDispatch(){let list=db.orders.filter(o=>['Ready for dispatch','Dispatched','Completed'].includes(o.stage));return `${header('OPERATIONS','Dispatch','Prepare, record and trace every outgoing shipment.',button('Create dispatch','dispatch-ready','primary-button','＋'))}<div class="tabs"><button class="tab active">All dispatches <span>${list.length}</span></button><button class="tab" data-dispatch-filter="Ready for dispatch">Ready to dispatch <span>${db.orders.filter(o=>o.stage==='Ready for dispatch').length}</span></button><button class="tab" data-dispatch-filter="Dispatched">Dispatched <span>${db.orders.filter(o=>o.stage==='Dispatched').length}</span></button><button class="tab" data-dispatch-filter="Completed">Completed <span>${db.orders.filter(o=>o.stage==='Completed').length}</span></button></div><section class="panel table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>ORDER</th><th>CLIENT</th><th>PRODUCT</th><th>QUANTITY</th><th>STAGE</th><th>DISPATCH DATE</th><th>CARRIER / TRACKING</th><th></th></tr></thead><tbody>${list.length?list.map(o=>`<tr data-order="${o.id}"><td class="id-cell">${o.id}</td><td>${esc(o.client)}</td><td>${esc(o.product)}</td><td>${o.qty} units</td><td>${chip(o.stage)}</td><td>${o.dispatch?fmtDate(o.dispatch.date):'—'}</td><td>${o.dispatch?`${esc(o.dispatch.carrier)}<small style="display:block;color:#9ca49f;margin-top:3px">${esc(o.dispatch.tracking)}</small>`:'—'}</td><td>${o.stage==='Ready for dispatch'?`<button class="compact-button" data-dispatch="${o.id}">Dispatch order</button>`:''}</td></tr>`).join(''):`<tr><td colspan="8" class="empty-state">No dispatch records yet.</td></tr>`}</tbody></table></div></section>`}
function renderReports(){let completed=db.orders.filter(o=>o.stage==='Completed').length,delayed=db.orders.filter(isLate).length,dispatched=db.orders.filter(o=>['Dispatched','Completed'].includes(o.stage)).length,jobDone=getJobs().filter(j=>j.p.status==='Completed').length,allJobs=getJobs().length;return `${header('INSIGHTS','Reports','A clear view of orders, production, inventory and team workload.',`<button class="secondary-button" data-action="export-report">↓ Export CSV</button>`)}<div class="toolbar"><select id="report-range"><option>Last 30 days</option><option>Last 7 days</option><option>This quarter</option><option>All time</option></select><span class="eyebrow">UPDATED ${fmtDate(new Date().toISOString().slice(0,10),{day:'numeric',month:'short',year:'numeric'})}</span></div><div class="report-grid"><section class="report-card"><h3>Order outcomes</h3><div class="report-row"><span>Total orders</span><strong>${db.orders.length}</strong></div><div class="report-row"><span>Completed</span><strong>${completed}</strong></div><div class="report-row"><span>Dispatched / complete</span><strong>${dispatched}</strong></div><div class="report-row"><span>Overdue active</span><strong>${delayed}</strong></div></section><section class="report-card"><h3>Production completion</h3><div class="bar-chart">${PROCESSES.map(p=>{let jj=getJobs().filter(j=>j.p.name===p),v=jj.length?Math.round(jj.filter(j=>j.p.status==='Completed').length/jj.length*100):0;return `<div class="bar-col"><span style="height:${v}%"></span><small>${p.split(' ')[0]}</small></div>`}).join('')}</div><div class="report-row"><span>Jobs completed</span><strong>${jobDone} / ${allJobs}</strong></div></section><section class="report-card"><h3>Material consumption</h3>${db.inventory.map(m=>`<div class="report-row"><span>${m.name}</span><strong>${m.consumed} ${m.unit}</strong></div>`).join('')}<div class="report-row"><span>Total wastage</span><strong>${db.inventory.reduce((a,m)=>a+m.wastage,0)} units</strong></div></section><section class="report-card"><h3>Orders by stage</h3>${STAGES.map(s=>`<div class="report-row"><span>${s}</span><strong>${db.orders.filter(o=>o.stage===s).length}</strong></div>`).join('')}</section><section class="report-card"><h3>Staff workload</h3>${PEOPLE.map(person=>`<div class="report-row"><span>${person}</span><strong>${getJobs().filter(j=>j.p.assigned===person&&!['Completed'].includes(j.p.status)).length} active</strong></div>`).join('')}</section><section class="report-card"><h3>Order deadlines</h3><div class="report-row"><span>Due in the next 3 days</span><strong>${activeOrders().filter(o=>daysLeft(o.deadline)>=0&&daysLeft(o.deadline)<=3).length}</strong></div><div class="report-row"><span>Overdue</span><strong class="risk">${delayed}</strong></div><div class="report-row"><span>On track</span><strong>${activeOrders().filter(o=>daysLeft(o.deadline)>3).length}</strong></div></section></div>`}
function renderStaff(){return `${header('WORKSPACE','Staff','Workload and assignments across the production team.',button('Add staff member','add-staff','secondary-button','＋'))}<div class="report-grid">${PEOPLE.map((p,i)=>{let jobs=getJobs().filter(j=>j.p.assigned===p),active=jobs.filter(j=>!['Completed'].includes(j.p.status)).length,done=jobs.length-active;return `<section class="report-card"><div style="display:flex;align-items:center;gap:10px;margin-bottom:13px"><span class="avatar">${p.split(' ').map(x=>x[0]).join('')}</span><div><h3 style="margin:0">${p}</h3><small style="color:#929b95;font-size:12px">${i===0?'Production lead':i===1?'Iron work':'Production staff'}</small></div>${chip(active?'Active':'Available')}</div><div class="report-row"><span>Active jobs</span><strong>${active}</strong></div><div class="report-row"><span>Completed jobs</span><strong>${done}</strong></div><div class="report-row"><span>Overdue jobs</span><strong class="${jobs.some(j=>j.p.status==='Delayed')?'risk':''}">${jobs.filter(j=>j.p.status==='Delayed').length}</strong></div></section>`}).join('')}</div>`}
function renderTimeline(items){return `<div class="timeline">${items.length?items.map(a=>`<div class="timeline-item"><time>${fmtTime(a.time)} · ${esc(a.actor)}</time><h4>${esc(a.text)}</h4><p>${esc(a.entity)}</p></div>`).join(''):`<div class="empty-state">No activity recorded.</div>`}</div>`}
function renderActivity(){let items=db.activity.filter(a=>activityFilter==='All'||a.actor===activityFilter);return `${header('WORKSPACE','Activity log','A permanent record of meaningful order, production and inventory changes.',`<select id="activity-filter" class="filter-search"><option>All</option>${[...new Set(db.activity.map(a=>a.actor))].map(p=>`<option ${activityFilter===p?'selected':''}>${esc(p)}</option>`).join('')}</select>`)}<section class="panel" style="max-width:800px"><div class="panel-header"><div><h2>Latest updates</h2><p>${items.length} events</p></div></div>${renderTimeline(items)}</section>`}
function renderSettings(){return `${header('WORKSPACE','Settings','Configure your operating stages, materials and workspace preferences.') }<div class="settings-grid"><nav class="settings-nav"><button class="active">Workflow</button><button data-action="role-switch">Roles & access</button><button data-action="reset-demo">Demo data</button></nav><section class="panel settings-content"><h2>Order lifecycle</h2><p style="font-size:12px;color:#8e9891">Orders follow these stages. Each transition is recorded in the activity history.</p>${STAGES.map((s,i)=>`<div class="setting-row"><div><strong>${String(i+1).padStart(2,'0')} · ${s}</strong><p>${i===0?'New order captured':i===2?'Production jobs are active':i===5?'Shipment handed to carrier':'Workflow milestone'}</p></div><span style="color:#9da69f">⠿</span></div>`).join('')}<div class="setting-row"><div><strong>Transfer workspace data</strong><p>Export orders, production tracker, staff changes, photos and the imported rope workbook as a JSON file.</p></div>${button('Export all data','export-data','secondary-button','↓')}</div><div class="info-banner" style="margin-top:15px">This workspace saves data in this browser. For multi-user authentication, shared live updates and a central database, connect a server-backed deployment.</div></section></div>`}
function rerenderPage(){render()}
document.addEventListener('click',e=>{const option=e.target.closest('[data-tracker-option]');if(option){let i=Number(option.dataset.trackerIndex),key=option.dataset.trackerKey;trackerRows[i][key]=option.dataset.trackerOption;localStorage.setItem('umami-production-tracker-v1',JSON.stringify(trackerRows));document.querySelector('.tracker-menu')?.remove();render();return}const trigger=e.target.closest('[data-tracker-index][data-tracker-options]');document.querySelector('[data-tracker-index][data-tracker-options][aria-expanded=\"true\"]')?.setAttribute('aria-expanded','false');document.querySelector('.tracker-menu')?.remove();if(trigger){const values=trigger.dataset.trackerOptions.split('|'),r=trigger.getBoundingClientRect(),menu=document.createElement('div');menu.className='tracker-menu';menu.setAttribute('role','listbox');menu.setAttribute('aria-label',trigger.getAttribute('aria-label'));menu.style.left=Math.max(8,Math.min(r.left,window.innerWidth-240))+'px';menu.style.top=Math.max(8,Math.min(r.bottom+4,window.innerHeight-Math.min(values.length*42+12,300)-8))+'px';menu.innerHTML=values.map(v=>`<button type="button" role="option" aria-selected="${v===trackerRows[Number(trigger.dataset.trackerIndex)][trigger.dataset.trackerKey]}" class="tracker-menu-option ${v===trackerRows[Number(trigger.dataset.trackerIndex)][trigger.dataset.trackerKey]?'selected':''}" data-tracker-option="${esc(v)}" data-tracker-index="${trigger.dataset.trackerIndex}" data-tracker-key="${trigger.dataset.trackerKey}">${esc(v||'—')}${v===trackerRows[Number(trigger.dataset.trackerIndex)][trigger.dataset.trackerKey]?'<span>✓</span>':''}</button>`).join('');document.body.appendChild(menu);trigger.setAttribute('aria-expanded','true');menu.querySelector('.selected')?.focus();return}let nav=e.target.closest('.nav-link');if(nav){page=nav.dataset.page;return}let row=e.target.closest('[data-order]');if(row&&!e.target.closest('button')){openOrder(row.dataset.order);return}let job=e.target.closest('[data-job]');if(job){openJob(job.dataset.job);return}let tab=e.target.closest('[data-order-filter]');if(tab){orderFilter=tab.dataset.orderFilter;render();return}let stage=e.target.closest('[data-stage]');if(stage){page='orders';orderFilter=stage.dataset.stage;location.hash='#orders';return}let disp=e.target.closest('[data-dispatch]');if(disp){openDispatch(disp.dataset.dispatch);return}let act=e.target.closest('[data-action]');if(act){runAction(act.dataset.action);return}let n=e.target.closest('#role-switch');if(n){db.role=db.role==='Admin'?'Staff':'Admin';save();toast(`Viewing as ${db.role}`);return}if(e.target.id==='notifications'){openNotifications();return}if(e.target.id==='mobile-menu'){document.querySelector('#sidebar').classList.toggle('open');return}if(e.target.id==='overlay-root'&&e.target.classList.contains('modal-backdrop')){e.target.innerHTML='';return}let close=e.target.closest('[data-close]');if(close){document.querySelector('#overlay-root').innerHTML='';return}let r=e.target.closest('.search-result');if(r){document.querySelector('#overlay-root').innerHTML='';document.querySelector('#global-search').value='';openOrder(r.dataset.order);return}let df=e.target.closest('[data-dispatch-filter]');if(df){document.querySelectorAll('[data-dispatch-filter]').forEach(x=>x.classList.remove('active'));df.classList.add('active');let stage=df.dataset.dispatchFilter;document.querySelectorAll('.data-table tbody tr[data-order]').forEach(tr=>tr.style.display=db.orders.find(o=>o.id===tr.dataset.order)?.stage===stage?'':'none');return}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.tracker-menu')){document.querySelector('.tracker-menu').remove();document.querySelector('[data-tracker-index][data-tracker-options][aria-expanded=\"true\"]')?.setAttribute('aria-expanded','false');document.querySelector('[data-tracker-index][data-tracker-options][aria-expanded="true"]')?.focus()}});
document.addEventListener('click',e=>{let t=e.target.closest('[data-rope-tab]');if(t){ropeInventoryTab=t.dataset.ropeTab;render();return}});
document.addEventListener('input',e=>{if(e.target.id==='rope-inventory-search'){ropeInventorySearch=e.target.value;let pos=e.target.selectionStart;render();let f=document.querySelector('#rope-inventory-search');f?.focus();f?.setSelectionRange(pos,pos);return}if(e.target.id==='tracker-search'){let pos=e.target.selectionStart;render();let input=document.querySelector('#tracker-search');input?.focus();input?.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.matches('[data-tracker-index]')){let row=trackerRows[Number(e.target.dataset.trackerIndex)];if(row){row[e.target.dataset.trackerKey]=e.target.value;localStorage.setItem('umami-production-tracker-v1',JSON.stringify(trackerRows));render()}}let id=e.target.id;if(id==='job-process')jobFilters.process=e.target.value;if(id==='job-status')jobFilters.status=e.target.value;if(id==='job-staff')jobFilters.staff=e.target.value;if(['job-process','job-status','job-staff'].includes(id))render();if(id==='activity-filter'){activityFilter=e.target.value;render()}if(id==='order-priority'||id==='order-deadline'){document.querySelectorAll('.data-table tbody tr[data-order]').forEach(tr=>{let o=db.orders.find(x=>x.id===tr.dataset.order);let p=document.querySelector('#order-priority')?.value||'All',d=document.querySelector('#order-deadline')?.value||'All';tr.style.display=(p==='All'||o.priority===p)&&(d==='All'||(d==='late'?isLate(o):daysLeft(o.deadline)<=3&&daysLeft(o.deadline)>=0))?'':'none'})}});
document.addEventListener('input',e=>{if(e.target.id==='job-search'){jobFilters.query=e.target.value;let pos=e.target.selectionStart;render();let x=document.querySelector('#job-search');x.focus();x.setSelectionRange(pos,pos)}if(e.target.id==='global-search')showSearch(e.target.value)});
document.addEventListener('submit',e=>{e.preventDefault();let f=e.target;if(f.id==='order-form')submitOrder(f);if(f.id==='job-update-form')submitJobUpdate(f);if(f.id==='transaction-form')submitTransaction(f);if(f.id==='dispatch-form')submitDispatch(f);if(f.id==='staff-form'){toast('Staff member added to workspace');document.querySelector('#overlay-root').innerHTML=''}});
window.addEventListener('hashchange',()=>{let wanted=location.hash.slice(1);if(['dashboard','orders','production','jobs','inventory','dispatch','reports','staff','activity','settings','guide'].includes(wanted)){page=wanted;document.querySelector('#sidebar').classList.remove('open');render()}});
function runAction(a){if(a==='new-order')openNewOrder();else if(a==='update-job')openUpdateJob();else if(a==='new-transaction')openTransaction();else if(a==='jobs'){page='jobs';location.hash='#jobs'}else if(a==='dispatch-ready'){let o=db.orders.find(o=>o.stage==='Ready for dispatch');o?openDispatch(o.id):toast('No orders are ready for dispatch yet.');}else if(a==='export-report')exportCSV();else if(a==='export-data')exportWorkspaceData();else if(a==='role-switch'){db.role=db.role==='Admin'?'Staff':'Admin';save();toast(`Viewing as ${db.role}`)}else if(a==='guide'){page='guide';location.hash='#guide';render()}else if(a==='reset-demo'){if(confirm('Reset this browser workspace to the original demo data?')){db=structuredClone(SEED);save();toast('Demo data restored.')}}else if(a==='add-staff')openStaffForm()}
function openNewOrder(){let id=`UM-${Math.max(1048,...db.orders.map(o=>Number(o.id.slice(3))||0))+1}`;document.querySelector('#overlay-root').innerHTML=`<div class="modal-backdrop"><section class="drawer"><div class="modal-heading"><div><div class="eyebrow">ORDER INTAKE · STEP 1 OF 1</div><h2>Create an order</h2><p>Capture the order once. Jobs, schedule and material checks will use these details.</p></div><button class="close-button" data-close>×</button></div><form id="order-form"><div class="form-grid"><div class="field"><label>Order ID</label><input name="id" value="${id}" readonly></div><div class="field"><label>Order source</label><select name="source"><option>Direct</option><option>Website</option><option>Referral</option><option>Trade show</option></select></div><div class="field"><label>Client name *</label><input name="client" required placeholder="e.g. Casa Forma"></div><div class="field"><label>Client contact</label><input name="contact" placeholder="Name · phone"></div><div class="field full"><div class="panel-header"><div><h2>Product lines</h2><p>Add each SKU in the order with its own production specifications.</p></div><button type="button" class="compact-button" data-add-order-line>＋ Add product</button></div><div class="order-line-entry" data-order-line><div class="order-line-entry-head"><strong>Product 1</strong><span>PHOTO AND COLOUR REFERENCE CAN BE ADDED BELOW</span></div><div class="form-grid"><div class="field"><label>SKU *</label><input name="lineSku" placeholder="e.g. UM-CH-045" required></div><div class="field"><label>Product name *</label><input name="lineName" placeholder="Chair, sofa, table…" required></div><div class="field"><label>Quantity *</label><input name="lineQty" type="number" min="1" value="1" required></div><div class="field"><label>Dimensions</label><input name="lineDimensions" placeholder="Width × depth × height"></div><div class="field"><label>Frame material</label><input name="lineMaterial" placeholder="Aluminium / CR / iron"></div><div class="field"><label>Powder colour</label><input name="linePowderColor" placeholder="e.g. black"></div><div class="field"><label>Dori colour</label><input name="lineDoriColour" placeholder="Rope colour"></div><div class="field"><label>Rope size / code</label><input name="lineRopeCode" placeholder="Size or code"></div><div class="field"><label>Rope required (m)</label><input name="lineRopeQty" type="number" min="0" step="0.1"></div><div class="field"><label>Fabric code</label><input name="lineFabricCode" placeholder="Fabric / upholstery code"></div><div class="field"><label>Fabric company</label><input name="lineFabricCompany" placeholder="Supplier / company"></div><div class="field"><label>Fabric quantity</label><input name="lineFabricQty" type="number" min="0" step="0.1"></div><div class="field"><label>Seat height</label><input name="lineSeatHeight"></div><div class="field"><label>Seat bifurcation</label><input name="lineSeatBifurcation"></div><div class="field"><label>Back cushion</label><input name="lineBackCushion"></div><div class="field"><label>Extra cushion</label><input name="lineExtraCushion"></div><div class="field"><label>Table top / stone</label><input name="lineTableTop" placeholder="Material, thickness, supplier"></div><div class="field"><label>Buffer type</label><input name="lineBufferType"></div></div></div><div data-extra-order-lines></div><input type="hidden" name="product" value="Product line"><input type="hidden" name="qty" value="1"></div><div class="field"><label>Priority</label><select name="priority"><option>Standard</option><option>High</option><option>Urgent</option></select></div><div class="field"><label>Order date *</label><input name="orderDate" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Sky date</label><input name="skyDate" type="date"></div><div class="field"><label>Required deadline *</label><input name="deadline" type="date" required></div><div class="field"><label>First production process</label><select name="firstProcess"><option>Iron Work</option><option>Rope Work</option><option>Fabric Work</option></select></div><div class="field"><label>Total rope required (m)</label><input name="rope" type="number" min="0" step="0.1" value="0"></div><div class="field"><label>Total fabric required (m)</label><input name="fabric" type="number" min="0" step="0.1" value="0"></div><div class="field full"><label>Order photo</label><input name="productPhoto" type="file" accept="image/*"><small class="field-hint">Upload a reference image for this order to make the model, colour and finish clear to the team.</small></div><div class="field full"><label>Order notes</label><textarea name="notes" placeholder="Specifications, finish, delivery instructions…"></textarea></div></div><div class="form-actions"><button type="button" class="secondary-button" data-close>Cancel</button><button class="primary-button">Create order & jobs →</button></div></form></section></div>`}
function submitOrder(f){let d=Object.fromEntries(new FormData(f)),items=[...f.querySelectorAll('[data-order-line]')].map(row=>{let get=n=>row.querySelector(`[name="${n}"]`)?.value?.trim()||'';return {sku:get('lineSku'),name:get('lineName'),qty:Number(get('lineQty'))||1,dimensions:get('lineDimensions'),material:get('lineMaterial'),powderColor:get('linePowderColor'),doriColour:get('lineDoriColour'),ropeCode:get('lineRopeCode'),ropeRequired:Number(get('lineRopeQty'))||0,fabricCode:get('lineFabricCode'),fabricCompany:get('lineFabricCompany'),fabricRequired:Number(get('lineFabricQty'))||0,seatHeight:get('lineSeatHeight'),seatBifurcation:get('lineSeatBifurcation'),backCushion:get('lineBackCushion'),extraCushion:get('lineExtraCushion'),tableTop:get('lineTableTop'),bufferType:get('lineBufferType')}}),q=items.reduce((n,x)=>n+x.qty,0),o={id:d.id,client:d.client,contact:d.contact,product:items.map(x=>x.name).join(', '),qty,items,orderDate:d.orderDate,skyDate:d.skyDate||d.deadline,deadline:d.deadline,priority:d.priority,stage:'Order received',source:d.source,notes:d.notes,materials:{Rope:Number(d.rope),Fabric:Number(d.fabric)},createdBy:currentActor(),createdAt:new Date().toISOString(),processes:PROCESSES.map((name,i)=>({name,completed:0,assigned:PEOPLE[i%PEOPLE.length],due:d.deadline,status:'Not started',material:name==='Rope Work'&&d.rope>0?'Rope':name==='Fabric Work'&&d.fabric>0?'Fabric':'',required:name==='Rope Work'?Number(d.rope):name==='Fabric Work'?Number(d.fabric):0,consumed:0,detail:''}))};let first=o.processes.find(p=>p.name===d.firstProcess);first.status='In progress';db.orders.unshift(o);addActivity(o.createdBy,o.id,'Order received and product lines and production jobs created');document.querySelector('#overlay-root').innerHTML='';save();toast(`${o.id} created with ${items.length} product lines and 3 job sheets.`)}
function openOrder(id){let o=db.orders.find(x=>x.id===id);if(!o)return;let idx=STAGES.indexOf(o.stage),ev=db.activity.filter(a=>a.entity===o.id||a.entity.startsWith(`JOB-${o.id.slice(3)}`));let mats=Object.entries(o.materials||{}).filter(x=>x[1]>0);document.querySelector('#overlay-root').innerHTML=`<div class="modal-backdrop"><section class="drawer"><div class="detail-header"><div class="detail-title"><div class="eyebrow">${o.id} · ${esc(o.source||'Direct')}</div><h2>${esc(o.client)}</h2><p>${esc(o.product)} · ${o.qty} units</p></div><div style="display:flex;gap:7px"><button class="secondary-button" data-edit-order="${o.id}">Edit</button><button class="close-button" data-close>×</button></div></div><div style="display:flex;align-items:center;gap:10px;margin-bottom:17px">${chip(o.stage)} <span class="eyebrow">${o.priority} PRIORITY</span><span style="margin-left:auto;font-size:12px;color:${isLate(o)?'var(--red)':'#7c8980'}">${isLate(o)?`${Math.abs(daysLeft(o.deadline))} days overdue`:daysLeft(o.deadline)>=0?`${daysLeft(o.deadline)} days to deadline`:'Complete'}</span></div><div class="tabs"><button class="tab active">Overview</button><button class="tab" data-order-tab="production">Production</button><button class="tab" data-order-tab="materials">Materials</button><button class="tab" data-order-tab="history">History</button></div><div class="detail-facts"><div><small>ORDER DATE</small><strong>${fmtDate(o.orderDate,{day:'numeric',month:'short',year:'numeric'})}</strong></div><div><small>SKY DATE</small><strong>${fmtDate(o.skyDate)}</strong></div><div><small>REQUIRED BY</small><strong class="${isLate(o)?'risk':''}">${fmtDate(o.deadline,{day:'numeric',month:'short',year:'numeric'})}</strong></div><div><small>CONTACT</small><strong>${esc(o.contact||'Not added')}</strong></div><div><small>PROGRESS</small><strong>${progress(o)}%</strong></div><div><small>ASSIGNED STAFF</small><strong>${esc([...new Set(o.processes.map(p=>p.assigned).filter(Boolean))].join(', ')||'Unassigned')}</strong></div></div><div class="panel-header" style="margin-top:18px"><h2>Order lifecycle</h2><button class="compact-button" data-advance="${o.id}">Advance stage →</button></div><div class="timeline">${STAGES.map((s,i)=>`<div class="timeline-item" style="opacity:${i<=idx?1:.48}"><time>${i===idx?'CURRENT STAGE':''}</time><h4>${i<idx?'✓ ':i===idx?'● ':'○ '}${s}</h4><p>${i===0?fmtDate(o.orderDate):i<idx?`Completed · ${fmtDate(o.orderDate)}`:i===idx?'In progress':'Pending'}</p></div>`).join('')}</div><div class="panel-header" style="margin-top:20px"><h2>Production jobs</h2><a class="panel-link" href="#jobs" data-close>All job sheets →</a></div>${o.processes.map(p=>`<div class="order-process"><span class="process-icon">${p.status==='Completed'?'✓':'◉'}</span><div style="min-width:100px"><strong>${p.name}</strong><small>${esc(p.assigned)} · due ${fmtDate(p.due)}</small></div><div class="progress-track"><span style="width:${Math.min(100,p.completed/o.qty*100)}%"></span></div><span style="font-size:12px;color:#758078">${p.completed}/${o.qty}</span>${chip(p.status)}</div>`).join('')}<div class="panel-header" style="margin-top:20px"><h2>Materials & availability</h2></div>${mats.length?mats.map(([m,q])=>{let stock=materialStock(m),short=Math.max(0,q-stock);return `<div class="material-row"><div><strong>${m} · ${q} ${db.inventory.find(x=>x.name===m)?.unit} required</strong><small>${short?`Short by ${short} ${db.inventory.find(x=>x.name===m)?.unit}`:'Available to reserve'}</small></div>${chip(short?'Low stock':'Ready')}</div>`}).join(''):'<p style="font-size:12px;color:#929b95">No material requirements added.</p>'}<div class="panel-header" style="margin-top:20px"><h2>Recent activity</h2></div>${renderTimeline(ev.slice(0,5))}${o.dispatch?`<section class="panel" style="margin-top:16px"><h2>Dispatch details</h2><p style="font-size:12px;color:#727e75">${fmtDate(o.dispatch.date)} · ${esc(o.dispatch.carrier)} · ${esc(o.dispatch.tracking)}</p></section>`:''}<div class="form-actions"><button class="secondary-button" data-update-order="${o.id}">Update order</button>${['Received','Being prepared','In production','Quality check'].includes(o.stage)?`<button class="primary-button" data-advance="${o.id}">Advance stage →</button>`:''}</div></section></div>`}
function openJob(id){let j=getJobs().find(x=>x.id===id);if(!j)return;let{o,p}=j,unit=db.inventory.find(m=>m.name===p.material)?.unit||'';document.querySelector('#overlay-root').innerHTML=`<div class="modal-backdrop"><section class="drawer narrow"><div class="modal-heading"><div><div class="eyebrow">JOB SHEET · ${id}</div><h2>${p.name}</h2><p>${o.id} · ${esc(o.client)} · ${esc(o.product)}</p></div><button class="close-button" data-close>×</button></div><div style="display:flex;gap:7px;align-items:center;margin-bottom:18px">${chip(p.status)}<span class="eyebrow">${o.priority} PRIORITY</span></div><div class="detail-facts"><div><small>REQUIRED</small><strong>${o.qty} units</strong></div><div><small>COMPLETED</small><strong>${p.completed} units</strong></div><div><small>REMAINING</small><strong>${o.qty-p.completed} units</strong></div><div><small>ASSIGNED TO</small><strong>${esc(p.assigned)}</strong></div><div><small>STARTED</small><strong>${p.started?fmtDate(p.started):'Not started'}</strong></div><div><small>DUE DATE</small><strong>${fmtDate(p.due)}</strong></div></div><div class="panel-header" style="margin-top:18px"><h2>Job progress</h2><strong>${Math.round(p.completed/o.qty*100)}%</strong></div><div class="progress-track" style="height:8px"><span style="width:${Math.min(100,p.completed/o.qty*100)}%"></span></div>${p.material?`<div class="panel-header" style="margin-top:21px"><h2>Material · ${p.material}</h2></div><div class="detail-facts"><div><small>REQUIRED</small><strong>${p.required} ${unit}</strong></div><div><small>CONSUMED</small><strong>${p.consumed} ${unit}</strong></div><div><small>REMAINING</small><strong>${Math.max(0,p.required-p.consumed)} ${unit}</strong></div></div>`:''}<div class="panel-header" style="margin-top:20px"><h2>Process notes</h2></div><p style="font-size:12px;color:#737f76;line-height:1.6">${esc(p.detail||'No process notes.')}</p><div class="form-actions"><button class="secondary-button" data-close>Close</button><button class="primary-button" data-job-update="${id}">Update job →</button></div><div class="panel-header" style="margin-top:20px"><h2>Activity history</h2></div>${renderTimeline(db.activity.filter(a=>a.entity===id).slice(0,6))}</section></div>`}
function openUpdateJob(preselected=''){let opts=getJobs().map(({o,p,id})=>`<option value="${id}" ${id===preselected?'selected':''}>${id} · ${p.name} · ${o.client}</option>`).join('');document.querySelector('#overlay-root').innerHTML=`<div class="modal-backdrop center"><section class="modal-card"><div class="modal-heading"><div><div class="eyebrow">PRODUCTION UPDATE</div><h2>Update a job sheet</h2><p>Record completed units, materials consumed and job status.</p></div><button class="close-button" data-close>×</button></div><form id="job-update-form"><div class="form-grid"><div class="field full"><label>Job sheet</label><select name="job" required><option value="">Select an active job</option>${opts}</select></div><div class="field"><label>Completed units</label><input name="completed" type="number" min="0" required></div><div class="field"><label>Job status</label><select name="status"><option>Not started</option><option>In progress</option><option>On hold</option><option>Completed</option><option>Delayed</option></select></div><div class="field"><label>Material consumed</label><input name="consumed" type="number" min="0" step="0.1" value="0"></div><div class="field"><label>Updated by</label><select name="staff">${PEOPLE.map(p=>`<option ${db.role==='Staff'&&p==='Amit Shah'?'selected':''}>${p}</option>`).join('')}</select></div><div class="field full"><label>Update notes</label><textarea name="notes" placeholder="Progress, quality notes or blockers…"></textarea></div></div><div class="form-actions"><button type="button" class="secondary-button" data-close>Cancel</button><button class="primary-button">Save update</button></div></form></section></div>`}
function submitJobUpdate(f){let d=Object.fromEntries(new FormData(f));d.staff=currentActor();let j=getJobs().find(x=>x.id===d.job);if(!j)return;let old=j.p.completed;j.p.completed=Math.max(0,Math.min(j.o.qty,Number(d.completed)));j.p.status=d.status;if(j.p.completed>=j.o.qty)j.p.status='Completed';if(j.p.completed>0&&!j.p.started)j.p.started=new Date().toISOString().slice(0,10);if(d.notes)j.p.detail=d.notes;let used=Number(d.consumed);if(used>0&&j.p.material){j.p.consumed+=used;let tr={id:`TX-${210+db.transactions.length}`,material:j.p.material,type:'Consumption',qty:used,order:j.o.id,job:j.id,staff:d.staff,date:new Date().toISOString().slice(0,10),notes:d.notes||`${j.p.name} update`};db.transactions.unshift(tr);let inv=db.inventory.find(m=>m.name===j.p.material);inv.consumed+=used;}let avg=progress(j.o);if(avg===100&&j.o.stage==='In production')j.o.stage='Quality check';addActivity(d.staff,j.id,`${j.p.name}: ${old} → ${j.p.completed} units · ${j.p.status}`);if(j.p.status==='Completed')addActivity('System',j.o.id,`${j.p.name} completed · production now ${avg}%`);document.querySelector('#overlay-root').innerHTML='';save();toast(`${j.p.name} updated. Order progress is now ${avg}%.`)}
function openTransaction(){document.querySelector('#overlay-root').innerHTML=`<div class="modal-backdrop center"><section class="modal-card"><div class="modal-heading"><div><div class="eyebrow">INVENTORY</div><h2>Record a stock transaction</h2><p>Update stock through a traceable movement.</p></div><button class="close-button" data-close>×</button></div><form id="transaction-form"><div class="form-grid"><div class="field"><label>Material</label><select name="material">${db.inventory.map(m=>`<option>${m.name}</option>`).join('')}</select></div><div class="field"><label>Transaction type</label><select name="type"><option>Incoming</option><option>Adjustment</option><option>Reservation</option><option>Consumption</option><option>Wastage</option></select></div><div class="field"><label>Quantity</label><input name="qty" type="number" step="0.1" min="0.1" required></div><div class="field"><label>Related order (optional)</label><select name="order"><option value="—">None</option>${db.orders.map(o=>`<option>${o.id}</option>`).join('')}</select></div><div class="field"><label>Staff</label><select name="staff">${PEOPLE.map(p=>`<option>${p}</option>`).join('')}</select></div><div class="field"><label>Date</label><input name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field full"><label>Notes</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button type="button" class="secondary-button" data-close>Cancel</button><button class="primary-button">Record transaction</button></div></form></section></div>`}
function submitTransaction(f){let d=Object.fromEntries(new FormData(f)),m=db.inventory.find(x=>x.name===d.material),q=Number(d.qty);if(d.type==='Incoming')m.incoming+=q;if(d.type==='Adjustment')m.adjustments+=q;if(d.type==='Reservation')m.reserved+=q;if(d.type==='Consumption')m.consumed+=q;if(d.type==='Wastage')m.wastage+=q;db.transactions.unshift({id:`TX-${210+db.transactions.length}`,material:d.material,type:d.type,qty:q,order:d.order,job:'—',staff:d.staff,date:d.date,notes:d.notes});addActivity(currentActor(),d.order!=='—'?d.order:d.material,`${d.type}: ${q} ${m.unit} ${d.order!=='—'?`for ${d.order}`:''}`);document.querySelector('#overlay-root').innerHTML='';save();toast(`${d.material} ${d.type.toLowerCase()} recorded.`)}
function openDispatch(id){let o=db.orders.find(x=>x.id===id);if(!o)return;if(o.stage!=='Ready for dispatch'&&!o.dispatch){toast('Move the order to Ready for dispatch first.');return}document.querySelector('#overlay-root').innerHTML=`<div class="modal-backdrop center"><section class="modal-card"><div class="modal-heading"><div><div class="eyebrow">DISPATCH · ${o.id}</div><h2>${o.dispatch?'Dispatch record':'Dispatch order'}</h2><p>${esc(o.client)} · ${o.qty} units · ${esc(o.product)}</p></div><button class="close-button" data-close>×</button></div><form id="dispatch-form"><input type="hidden" name="id" value="${o.id}"><div class="form-grid"><div class="field"><label>Dispatch date</label><input name="date" type="date" value="${o.dispatch?.date||new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Dispatch person</label><select name="person">${PEOPLE.map(p=>`<option ${o.dispatch?.person===p?'selected':''}>${p}</option>`).join('')}</select></div><div class="field"><label>Carrier / transport</label><input name="carrier" value="${esc(o.dispatch?.carrier||'') }" placeholder="e.g. Blue Dart" required></div><div class="field"><label>Tracking / reference</label><input name="tracking" value="${esc(o.dispatch?.tracking||'') }" placeholder="Tracking number"></div><div class="field"><label>Quantity dispatched</label><input name="quantity" type="number" min="1" max="${o.qty}" value="${o.dispatch?.quantity||o.qty}" required></div><div class="field"><label>Dispatch status</label><select name="status"><option>Dispatched</option><option>Completed</option></select></div><div class="field full"><label>Dispatch notes</label><textarea name="notes">${esc(o.dispatch?.notes||'')}</textarea></div></div><div class="form-actions"><button type="button" class="secondary-button" data-close>Cancel</button><button class="primary-button">Save dispatch</button></div></form></section></div>`}
function submitDispatch(f){let d=Object.fromEntries(new FormData(f)),o=db.orders.find(x=>x.id===d.id);o.dispatch={date:d.date,person:d.person,carrier:d.carrier,tracking:d.tracking,quantity:Number(d.quantity),notes:d.notes};o.stage=d.status;db.dispatches.unshift({order:o.id,...o.dispatch});addActivity(currentActor(),o.id,`Dispatched ${d.quantity} units via ${d.carrier}${d.tracking?` · ${d.tracking}`:''}`);document.querySelector('#overlay-root').innerHTML='';save();toast(`${o.id} dispatch recorded.`)}
function openNotifications(){let al=alerts();document.querySelector('#overlay-root').innerHTML=`<div class="modal-backdrop"><section class="drawer narrow"><div class="modal-heading"><div><div class="eyebrow">OPERATIONS ALERTS</div><h2>Notifications</h2><p>Deadlines and materials that need attention.</p></div><button class="close-button" data-close>×</button></div>${al.length?al.map(a=>`<div class="alert-row"><span class="attention-icon ${a.tone}">${a.icon}</span><div><strong>${esc(a.title)}</strong><p>${esc(a.detail)}</p><time>${esc(a.time)}</time></div></div>`).join(''):'<div class="empty-state">You’re all caught up.</div>'}</section></div>`}
function openStaffForm(){document.querySelector('#overlay-root').innerHTML=`<div class="modal-backdrop center"><section class="modal-card"><div class="modal-heading"><div><h2>Add staff member</h2><p>Add a team member to assignment lists.</p></div><button class="close-button" data-close>×</button></div><form id="staff-form"><div class="form-grid"><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Role</label><select><option>Production staff</option><option>Production lead</option><option>Administrator</option></select></div></div><div class="form-actions"><button type="button" class="secondary-button" data-close>Cancel</button><button class="primary-button">Add staff</button></div></form></section></div>`}
function showSearch(q){let old=document.querySelector('.search-results');if(old)old.remove();if(!q.trim())return;let val=q.toLowerCase(),o=db.orders.filter(x=>`${x.id} ${x.client} ${x.product}`.toLowerCase().includes(val)).slice(0,4),j=getJobs().filter(x=>`${x.id} ${x.p.name} ${x.p.assigned}`.toLowerCase().includes(val)).slice(0,3),m=db.inventory.filter(x=>x.name.toLowerCase().includes(val));let html=[...o.map(x=>`<div class="search-result" data-order="${x.id}"><strong>${x.id} · ${esc(x.client)}</strong><small>Order · ${esc(x.product)} · ${x.stage}</small></div>`),...j.map(x=>`<div class="search-result" data-order="${x.o.id}"><strong>${x.id} · ${x.p.name}</strong><small>Job sheet · ${esc(x.p.assigned)} · ${esc(x.o.client)}</small></div>`),...m.map(x=>`<div class="search-result" data-page-result="inventory"><strong>${x.name} · ${materialStock(x.name)} ${x.unit} available</strong><small>Inventory material</small></div>`)].join('');if(!html)html='<div class="empty-state">No matching orders, jobs or materials.</div>';let d=document.createElement('div');d.className='search-results';d.innerHTML=html;document.body.appendChild(d)}
function exportCSV(){let rows=[['Order ID','Client','Product','Quantity','Stage','Deadline','Progress','Priority'],...db.orders.map(o=>[o.id,o.client,o.product,o.qty,o.stage,o.deadline,`${progress(o)}%`,o.priority])];let csv=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='umami-order-report.csv';a.click();URL.revokeObjectURL(a.href);toast('Order report exported.')}
function exportWorkspaceData(){const payload={exportedAt:new Date().toISOString(),source:location.origin,workspace:db.workspaceName||'Umami Studios',ordersAndOperations:db,productionTracker:trackerRows,ropeInventory:ropeSheetData};const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.href=url;a.download=`umami-workspace-data-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Workspace data exported as JSON.')}
// Supplemental delegated handlers for detail actions and workflow transitions.
document.addEventListener('click',e=>{
 const advance=e.target.closest('[data-advance]');if(advance){advanceOrder(advance.dataset.advance);return}
 const update=e.target.closest('[data-job-update]');if(update){openUpdateJob(update.dataset.jobUpdate);return}
 const edit=e.target.closest('[data-edit-order],[data-update-order]');if(edit){openEditOrder(edit.dataset.editOrder||edit.dataset.updateOrder);return}
 const tab=e.target.closest('[data-order-tab]');if(tab){document.querySelectorAll('[data-order-tab]').forEach(x=>x.classList.toggle('active',x===tab));const target=tab.dataset.orderTab;document.querySelector(target==='production'?'.order-process':target==='materials'?'.material-row':'.timeline')?.scrollIntoView({behavior:'smooth'});return}
 const sr=e.target.closest('.search-result');if(sr?.dataset.pageResult){document.querySelector('.search-results')?.remove();document.querySelector('#global-search').value='';page=sr.dataset.pageResult;location.hash=`#${page}`}
});
document.addEventListener('submit',e=>{if(e.target.id!=='edit-order-form')return;e.preventDefault();let f=e.target,o=db.orders.find(x=>x.id===f.dataset.id),d=Object.fromEntries(new FormData(f));let old=o.deadline,prior={client:o.client,contact:o.contact,product:o.product,qty:String(o.qty),priority:o.priority,skyDate:o.skyDate||'',deadline:o.deadline,notes:o.notes||''};Object.assign(o,{client:d.client,contact:d.contact,product:d.product,qty:Number(d.qty),priority:d.priority,skyDate:d.skyDate,deadline:d.deadline,notes:d.notes});o.processes.forEach(p=>{p.completed=Math.min(p.completed,o.qty)});if(old!==o.deadline)addActivity(currentActor(),o.id,`Deadline changed: ${fmtDate(old)} → ${fmtDate(o.deadline)}`);for(const field of ['client','contact','product','qty','priority','skyDate','deadline','notes']){const next=String(d[field]??'');if(String(prior[field]??'')!==next&&field!=='deadline')addActivity(currentActor(),o.id,`${field}: ${prior[field]||'—'} → ${next||'—'}`)}addActivity(currentActor(),o.id,'Order details updated');document.querySelector('#overlay-root').innerHTML='';save();toast(`${o.id} details saved.`)});
function advanceOrder(id){let o=db.orders.find(x=>x.id===id);if(!o)return;let progression={'Order received':'Being prepared','Being prepared':'In production','In production':'Quality check','Quality check':'Ready for dispatch','Dispatched':'Completed'};if(o.stage==='In production'&&o.processes.some(p=>p.status!=='Completed')){toast('Complete all process jobs before quality check.');return}if(o.stage==='Ready for dispatch'){document.querySelector('#overlay-root').innerHTML='';page='dispatch';location.hash='#dispatch';toast('Record the carrier details to dispatch this order.');return}let next=progression[o.stage];if(!next){toast('This order cannot advance from its current stage.');return}let before=o.stage;o.stage=next;addActivity(currentActor(),o.id,`Stage changed: ${before} → ${next}`);save();openOrder(id);toast(`${o.id} moved to ${next}.`)}
function openEditOrder(id){let o=db.orders.find(x=>x.id===id);if(!o)return;document.querySelector('#overlay-root').innerHTML=`<div class="modal-backdrop center"><section class="modal-card"><div class="modal-heading"><div><div class="eyebrow">ORDER DETAILS · ${o.id}</div><h2>Update order</h2><p>Client and product details stay linked to all production views.</p></div><button class="close-button" data-close>×</button></div><form id="edit-order-form" data-id="${o.id}"><div class="form-grid"><div class="field"><label>Client</label><input name="client" value="${esc(o.client)}" required></div><div class="field"><label>Contact</label><input name="contact" value="${esc(o.contact||'')}"></div><div class="field full"><label>Product</label><input name="product" value="${esc(o.product)}" required></div><div class="field"><label>Quantity</label><input name="qty" type="number" min="1" value="${o.qty}" required></div><div class="field"><label>Priority</label><select name="priority">${['Standard','High','Urgent'].map(s=>`<option ${o.priority===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Sky date</label><input name="skyDate" type="date" value="${o.skyDate||''}"></div><div class="field"><label>Required deadline</label><input name="deadline" type="date" value="${o.deadline}" required></div><div class="field full"><label>Notes</label><textarea name="notes">${esc(o.notes||'')}</textarea></div></div><div class="form-actions"><button type="button" class="secondary-button" data-close>Cancel</button><button class="primary-button">Save order</button></div></form></section></div>`}
render();

// Make role switching discoverable through explicit Admin and Staff choices.
document.addEventListener('click',e=>{
 const toggle=e.target.closest('#role-menu-toggle');const menu=document.querySelector('#role-menu');
 if(toggle){menu.hidden=!menu.hidden;toggle.setAttribute('aria-expanded',String(!menu.hidden));return}
 const option=e.target.closest('[data-set-role]');if(option){db.role=option.dataset.setRole;menu.hidden=true;document.querySelector('#role-menu-toggle').setAttribute('aria-expanded','false');save();toast(`Switched to ${db.role==='Admin'?'Admin':'Staff'} view.`);return}
 if(menu&&!e.target.closest('#role-menu')){menu.hidden=true;document.querySelector('#role-menu-toggle').setAttribute('aria-expanded','false')}
});
const roleMenuRender=render;render=function(){roleMenuRender();document.querySelectorAll('[data-set-role]').forEach(x=>x.classList.toggle('selected',x.dataset.setRole===db.role))};
render();

// Workspace selector reflects the active studio and links to editable workspace settings.
db.workspaceName=db.workspaceName||'Umami Studios';
const baseRenderSettings=renderSettings;
renderSettings=function(){return baseRenderSettings().replace('<section class="panel settings-content">',`<section class="panel settings-content"><div class="workspace-config"><h3>Workspace profile</h3><p>Set the name shown in the workspace selector.</p><form id="workspace-form"><input name="workspaceName" aria-label="Workspace name" value="${esc(db.workspaceName)}" required maxlength="48"><button class="primary-button">Save name</button></form></div>`)};
function syncWorkspaceName(){document.querySelector('#workspace-name').textContent=db.workspaceName||'Umami Studios';document.querySelector('#workspace-menu-name').textContent=db.workspaceName||'Umami Studios'}
document.addEventListener('click',e=>{const switcher=e.target.closest('#workspace-switcher');const menu=document.querySelector('#workspace-menu');if(switcher){menu.hidden=!menu.hidden;switcher.setAttribute('aria-expanded',String(!menu.hidden));return}if(e.target.closest('[data-action="workspace-settings"]')){menu.hidden=true;document.querySelector('#workspace-switcher').setAttribute('aria-expanded','false');page='settings';location.hash='#settings';render();return}if(menu&&!e.target.closest('#workspace-menu')){menu.hidden=true;document.querySelector('#workspace-switcher').setAttribute('aria-expanded','false')}});
document.addEventListener('submit',e=>{if(e.target.id!=='workspace-form')return;e.preventDefault();const d=Object.fromEntries(new FormData(e.target));db.workspaceName=d.workspaceName.trim();addActivity(db.role==='Admin'?'Shubham Jain':(window.staffMember||'Amit Shah'),'Workspace',`Workspace renamed to ${db.workspaceName}`);save();syncWorkspaceName();toast('Workspace name saved.')});
const renderWithWorkspace=render;render=function(){renderWithWorkspace();syncWorkspaceName()};
render();

// Save product reference photos on the related order record.
document.addEventListener('submit',e=>{if(e.target.id!=='order-form')return;const form=e.target;const file=form.elements.productPhoto?.files?.[0];if(!file)return;const orderId=form.elements.id.value;const reader=new FileReader();reader.onload=()=>{const o=db.orders.find(x=>x.id===orderId);if(o){o.photoData=reader.result;addActivity(currentActor(),orderId,'Product reference photo attached');save();toast('Product photo attached to '+orderId+'.')}};reader.readAsDataURL(file)},true);

// Role-specific staff workspace and QC/photo controls.
function renderStaffDashboard(){
 const person=window.staffMember||'Amit Shah';const assigned=getJobs().filter(j=>j.p.assigned===person);const active=assigned.filter(j=>j.p.status!=='Completed');const qc=assigned.flatMap(j=>j.p.qc.filter(c=>c.status!=='Passed'&&j.p.steps.find(step=>step.key===c.key)?.status==='Completed').map(c=>({...j,checkpoint:c})));const today=active.filter(j=>daysLeft(j.p.due)<=0).length;
 return `${header('STAFF WORKSPACE',`Your work, ${esc(person.split(' ')[0])}`,'Your assigned production jobs, QC checks and order reference photos.',`<select id="staff-person" class="filter-search">${PEOPLE.map(p=>`<option ${p===person?'selected':''}>${p}</option>`).join('')}</select>`)}<section class="kpi-grid"><article class="kpi-card"><div class="kpi-top"><span>MY ACTIVE JOBS</span><span class="kpi-icon">◉</span></div><div class="kpi-value">${active.length}</div><div class="kpi-foot">Assigned to you</div></article><article class="kpi-card"><div class="kpi-top"><span>QC CHECKS</span><span class="kpi-icon">✓</span></div><div class="kpi-value">${qc.length}</div><div class="kpi-foot">Waiting for your inspection</div></article><article class="kpi-card"><div class="kpi-top"><span>DUE TODAY / OVERDUE</span><span class="kpi-icon">◷</span></div><div class="kpi-value">${today}</div><div class="kpi-foot">Jobs that need attention</div></article><article class="kpi-card"><div class="kpi-top"><span>COMPLETED</span><span class="kpi-icon">✓</span></div><div class="kpi-value">${assigned.length-active.length}</div><div class="kpi-foot">Your completed jobs</div></article></section><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2>My jobs</h2><p>Open a job sheet to update progress or attach a product reference photo.</p></div><a class="panel-link" href="#jobs">All my jobs →</a></div>${active.length?active.map(({o,p,id})=>`<article class="staff-job-row"><button class="staff-job-main" data-job="${id}"><span class="process-icon">${p.status==='Delayed'?'!':'◉'}</span><span><strong>${id} · ${p.name}</strong><small>${o.id} · ${esc(o.client)} · ${esc(o.product)}</small><small>${p.completed}/${o.qty} units · due ${fmtDate(p.due)}</small></span><span>${chip(p.status)}</span></button><div class="staff-job-tools">${o.photoData?`<img src="${o.photoData}" alt="${esc(o.product)} reference photo" class="product-thumb">`:'<span class="photo-placeholder">No product photo</span>'}<button class="compact-button" data-upload-photo="${o.id}">＋ ${o.photoData?'Replace photo':'Add product photo'}</button><input class="photo-input" type="file" accept="image/*" data-photo-input="${o.id}" hidden></div></article>`).join(''):'<div class="empty-state">No active jobs are assigned to this team member.</div>'}</section><section class="panel"><div class="panel-header"><div><h2>Quality checks</h2><p>Inspect each production milestone before it moves forward.</p></div><span class="status amber">${qc.length} pending</span></div>${qc.length?qc.map(({o,p,id,checkpoint})=>`<div class="qc-row"><span class="qc-mark">✓</span><div><strong>${checkpoint.label}</strong><small>${o.id} · ${esc(o.client)} · ${p.name}</small></div><button class="compact-button" data-qc="${id}" data-checkpoint="${checkpoint.key}">Inspect</button></div>`).join(''):'<div class="empty-state">No QC checks waiting on your jobs.</div>'}<div class="info-banner" style="margin-top:14px">After framework fabrication, inspect the frame. After powder coating, inspect the finish. Rope and fabric work each have their own quality check.</div></section></div><div class="panel" style="margin-top:15px"><div class="panel-header"><div><h2>Quick actions</h2><p>Record work as it happens. Progress and material usage roll up to the order.</p></div></div><div style="display:flex;gap:9px;flex-wrap:wrap">${button('Update a job','update-job','primary-button','＋')}<a class="secondary-button" href="#jobs">Open my job sheets →</a></div></div>`
}
function qcRows(j){return `<section class="qc-section"><div class="panel-header"><div><h2>Quality checks</h2><p>Record each inspection before the product moves to the next step.</p></div></div>${j.p.qc.map(c=>`<div class="qc-row"><span class="qc-mark">${c.status==='Passed'?'✓':'○'}</span><div><strong>${esc(c.label)}</strong><small>${c.status==='Passed'?`Passed · ${esc(c.by||'Team member')} · ${c.date?fmtDate(c.date,{day:'numeric',month:'short',year:'numeric'}):''}`:c.status==='Rework required'?'Rework required':'Inspection pending'}${c.note?` · ${esc(c.note)}`:''}</small></div>${c.status==='Passed'?chip('Passed'):`<button class="compact-button" data-qc="${j.id}" data-checkpoint="${c.key}">Inspect</button>`}</div>`).join('')}</section>`}
function openQC(id,key){let j=getJobs().find(x=>x.id===id);if(!j)return;let c=j.p.qc.find(x=>x.key===key);if(!c)return;document.querySelector('#overlay-root').innerHTML=`<div class="modal-backdrop center"><section class="modal-card"><div class="modal-heading"><div><div class="eyebrow">QUALITY CHECK · ${id}</div><h2>${esc(c.label)}</h2><p>${j.o.id} · ${esc(j.o.client)} · ${esc(j.o.product)}</p></div><button class="close-button" data-close>×</button></div><div class="info-banner">Inspect the actual product at this production milestone. Record pass or rework and add a note so the next team member knows what to do.</div><form id="qc-form"><input type="hidden" name="job" value="${id}"><input type="hidden" name="checkpoint" value="${key}"><div class="field"><label>Inspection result</label><select name="status"><option>Passed</option><option>Rework required</option></select></div><div class="field" style="margin-top:12px"><label>Inspection notes</label><textarea name="note" placeholder="Colour, finish, dimensions, stability, defects…"></textarea></div><div class="form-actions"><button type="button" class="secondary-button" data-close>Cancel</button><button class="primary-button">Save QC result</button></div></form></section></div>`}
const baseOpenJob=openJob;openJob=function(id){baseOpenJob(id);let j=getJobs().find(x=>x.id===id),drawer=document.querySelector('#overlay-root .drawer');if(j&&drawer)drawer.querySelector('.detail-facts')?.insertAdjacentHTML('afterend',qcRows(j))};
const baseRender=render;render=function(){if(db.role==='Staff'){window.staffMember=window.staffMember||'Amit Shah';if(page==='jobs')jobFilters.staff=window.staffMember}baseRender();const profile=document.querySelector('.user-profile');if(profile){profile.querySelector('strong').textContent=db.role==='Admin'?'Shubham Jain':(window.staffMember||'Amit Shah');profile.querySelector('.avatar').textContent=db.role==='Admin'?'SJ':(window.staffMember||'Amit Shah').split(' ').map(x=>x[0]).join('')}document.querySelectorAll('.nav-link').forEach(a=>{const staffOnlyVisible=['dashboard','orders','production','jobs','inventory'];a.style.display=db.role==='Staff'?(staffOnlyVisible.includes(a.dataset.page)?'flex':'none'):'flex'});document.querySelectorAll('.nav-group').forEach(g=>{g.style.display=[...g.querySelectorAll('.nav-link')].some(a=>a.style.display!=='none')?'':'none'})};
const baseSave=save;let priorRole=db.role;save=function(){if(db.role!==priorRole){priorRole=db.role;page='dashboard';location.hash='#dashboard'}baseSave()};
document.addEventListener('change',e=>{if(e.target.id==='staff-person'){window.staffMember=e.target.value;jobFilters.staff=window.staffMember;render()}if(e.target.matches('[data-photo-input]')){const file=e.target.files?.[0];if(!file)return;const id=e.target.dataset.photoInput,reader=new FileReader();reader.onload=()=>{const o=db.orders.find(x=>x.id===id);if(o){o.photoData=reader.result;addActivity(currentActor(),id,'Product reference photo updated');save();toast('Product photo saved to '+id+'.')}};reader.readAsDataURL(file)}});
document.addEventListener('click',e=>{const upload=e.target.closest('[data-upload-photo]');if(upload){document.querySelector(`[data-photo-input="${upload.dataset.uploadPhoto}"]`)?.click();return}const qc=e.target.closest('[data-qc]');if(qc){openQC(qc.dataset.qc,qc.dataset.checkpoint)}});
document.addEventListener('submit',e=>{if(e.target.id!=='qc-form')return;e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),j=getJobs().find(x=>x.id===d.job),c=j?.p.qc.find(x=>x.key===d.checkpoint);if(!j||!c)return;c.status=d.status;c.note=d.note;c.by=window.staffMember||'Amit Shah';c.date=new Date().toISOString().slice(0,10);c.by=currentActor();addActivity(c.by,j.id,`${c.label}: ${c.status}${c.note?` · ${c.note}`:''}`);document.querySelector('#overlay-root').innerHTML='';save();toast('QC result recorded for '+j.id+'.')});
render();

const baseOpenOrder=openOrder;openOrder=function(id){baseOpenOrder(id);const o=db.orders.find(x=>x.id===id),drawer=document.querySelector('#overlay-root .drawer');if(!o||!drawer)return;const img=o.photoData?`<img class="product-photo" src="${o.photoData}" alt="${esc(o.product)} reference photo">`:'';drawer.querySelector('.detail-header')?.insertAdjacentHTML('afterend',img)};
const originalAdvance=advanceOrder;advanceOrder=function(id){const o=db.orders.find(x=>x.id===id);if(o?.stage==='In production'&&o.processes.some(p=>p.qc?.some(c=>c.status!=='Passed'))){toast('Complete and pass every production-stage QC check before moving this order to final quality check.');return}originalAdvance(id)};

// Stage-level production work sits beside its QC gate on every job sheet.
qcRows=function(j){
 const rows=j.p.steps.map((step,i)=>{
  const previous=j.p.steps[i-1];
  const priorQc=previous&&j.p.qc.find(c=>c.key===previous.key);
  const blocked=!!previous&&priorQc?.status!=='Passed';
  const button=step.status==='Completed'?chip('Completed'):`<button class="compact-button" data-step="${j.id}" data-step-key="${step.key}" ${blocked?'disabled':''}>${step.status==='Not started'?'Start step':'Mark complete'}</button>`;
  const qc=j.p.qc.filter(c=>c.key===step.key).map(c=>{
   const status=c.status==='Passed'?chip('Passed'):`<button class="compact-button" data-qc="${j.id}" data-checkpoint="${c.key}" ${step.status!=='Completed'?'disabled':''}>Inspect</button>`;
   const note=c.status==='Passed'?`Passed · ${esc(c.by||'Team member')}`:c.status==='Rework required'?'Rework required':'QC required before next step';
   return `<div class="qc-row qc-subrow"><span class="qc-mark">${c.status==='Passed'?'✓':'○'}</span><div><strong>${esc(c.label)}</strong><small>${note}</small></div>${status}</div>`;
  }).join('');
  return `<div class="qc-row"><span class="qc-mark">${step.status==='Completed'?'✓':step.status==='In progress'?'◉':'○'}</span><div><strong>${esc(step.label)}</strong><small>${esc(step.status)}${blocked?' · waiting for previous QC':''}</small></div>${button}</div>${qc}`;
 }).join('');
 return `<section class="qc-section"><div class="panel-header"><div><h2>Production steps</h2><p>Complete each step, then record its QC before continuing.</p></div></div>${rows}</section>`;
};
const baseOpenQC=openQC;openQC=function(id,key){const j=getJobs().find(x=>x.id===id),step=j?.p.steps.find(x=>x.key===key);if(step?.status!=='Completed'){toast('Complete this production step before recording QC.');return}baseOpenQC(id,key)};
function updateProductionStep(id,key){const j=getJobs().find(x=>x.id===id);if(!j)return;const i=j.p.steps.findIndex(x=>x.key===key),step=j.p.steps[i],previous=j.p.steps[i-1];if(previous&&j.p.qc.find(c=>c.key===previous.key)?.status!=='Passed'){toast('Pass the previous step’s QC before continuing.');return}if(step.status==='Not started')step.status='In progress';else if(step.status==='In progress')step.status='Completed';else return;addActivity(currentActor(),j.id,`${step.label} marked ${step.status.toLowerCase()}`);save();toast(`${step.label}: ${step.status}.`)}
document.addEventListener('click',e=>{const step=e.target.closest('[data-step]');if(step){updateProductionStep(step.dataset.step,step.dataset.stepKey)}});

const attributedOpenOrder=openOrder;openOrder=function(id){attributedOpenOrder(id);const o=db.orders.find(x=>x.id===id),drawer=document.querySelector('#overlay-root .drawer');if(!o||!drawer)return;const last=db.activity.find(a=>a.entity===id||a.entity.startsWith(`JOB-${id.slice(3)}`));const actor=o.updatedBy||last?.actor||'No updates yet',when=o.updatedAt||last?.time;const audit=`<div class="order-audit"><div><small>CREATED BY</small><strong>${esc(o.createdBy||'Unknown')}</strong><time>${o.createdAt?fmtTime(o.createdAt):'Creation time unavailable'}</time></div><div><small>LAST UPDATED BY</small><strong>${esc(actor)}</strong><time>${when?fmtTime(when):'No edits recorded'}</time></div></div>`;drawer.querySelector('.detail-facts')?.insertAdjacentHTML('afterend',audit)};

document.addEventListener('click',e=>{const add=e.target.closest('[data-add-order-line]');if(add){const source=document.querySelector('#order-form [data-order-line]'),host=document.querySelector('[data-extra-order-lines]');if(!source||!host)return;const row=source.cloneNode(true),count=document.querySelectorAll('#order-form [data-order-line]').length+1;row.querySelector('.order-line-entry-head strong').textContent=`Product ${count}`;row.querySelectorAll('input').forEach(i=>i.value=i.name==='lineQty'?'1':'');row.insertAdjacentHTML('afterbegin','<button type="button" class="line-remove" aria-label="Remove product line">Remove line</button>');host.appendChild(row)}const remove=e.target.closest('.line-remove');if(remove){remove.closest('[data-order-line]')?.remove();document.querySelectorAll('#order-form [data-order-line] .order-line-entry-head strong').forEach((x,i)=>x.textContent=`Product ${i+1}`)}});

const openWithOrderLines=openOrder;openOrder=function(id){openWithOrderLines(id);const o=db.orders.find(x=>x.id===id),drawer=document.querySelector('#overlay-root .drawer');if(!o||!drawer||!o.items?.length)return;const lineCards=o.items.map((it,i)=>{const facts=[['DIMENSIONS',it.dimensions],['FRAME MATERIAL',it.material],['POWDER COLOUR',it.powderColor],['DORI COLOUR',it.doriColour],['ROPE SIZE / CODE',it.ropeCode],['ROPE REQUIRED',it.ropeRequired?`${it.ropeRequired} m`:'' ],['FABRIC CODE',it.fabricCode],['FABRIC COMPANY',it.fabricCompany],['FABRIC REQUIRED',it.fabricRequired],['SEAT HEIGHT',it.seatHeight],['SEAT BIFURCATION',it.seatBifurcation],['BACK CUSHION',it.backCushion],['EXTRA CUSHION',it.extraCushion],['TABLE TOP / STONE',it.tableTop],['BUFFER TYPE',it.bufferType]].filter(([,v])=>v);return `<article class="order-line-card">${it.photoData?`<img class="product-photo" src="${it.photoData}" alt="${esc(it.name)} product reference">`:''}<div class="order-line-heading"><div><span class="eyebrow">PRODUCT ${i+1} · ${esc(it.sku||'NO SKU')}</span><h3>${esc(it.name)}</h3></div><strong>${it.qty} units</strong></div><button class="compact-button" type="button" data-upload-line-photo="${o.id}" data-line-index="${i}">＋ ${it.photoData?'Replace':'Add'} this product photo</button><input class="photo-input" type="file" accept="image/*" data-line-photo-input="${o.id}" data-line-index="${i}" hidden><div class="order-line-facts">${facts.map(([label,value])=>`<div><small>${label}</small><strong>${esc(value)}</strong></div>`).join('')}</div></article>`}).join('');drawer.querySelector('.detail-facts')?.insertAdjacentHTML('beforebegin',`<section class="order-lines-panel"><div class="panel-header"><div><h2>Order product lines</h2><p>SKU-specific production details from the order intake.</p></div><span class="eyebrow">${o.items.length} PRODUCTS</span></div>${lineCards}</section>`)};
document.addEventListener('click',e=>{const upload=e.target.closest('[data-upload-line-photo]');if(upload)document.querySelector(`[data-line-photo-input="${upload.dataset.uploadLinePhoto}"][data-line-index="${upload.dataset.lineIndex}"]`)?.click()});
document.addEventListener('change',e=>{const input=e.target.closest('[data-line-photo-input]');if(!input)return;const file=input.files?.[0];if(!file)return;const id=input.dataset.linePhotoInput,index=Number(input.dataset.lineIndex),reader=new FileReader();reader.onload=()=>{const o=db.orders.find(x=>x.id===id),item=o?.items?.[index];if(!item)return;item.photoData=reader.result;addActivity(currentActor(),id,`Product photo updated for ${item.sku||item.name}`);localStorage.setItem(STORAGE_KEY,JSON.stringify(db));openOrder(id);toast(`Photo saved for ${item.sku||item.name}.`)};reader.readAsDataURL(file)});

const IRON_QC_CHECKS=[['dimensions','Dimensions verified'],['material','Material verified'],['pipe','Pipe section verified'],['welding','Welding quality approved'],['grinding','Grinding & finishing complete'],['powder','Powder coating approved'],['level','Frame level & wobble-free'],['surface','No dents / scratches'],['hardware','Hardware / adjusters fitted'],['final','Final approval']];
db.orders.forEach(o=>o.processes.filter(p=>p.name==='Iron Work').forEach(p=>{p.checklist=p.checklist||IRON_QC_CHECKS.map(([key,label])=>({key,label,done:false}))}));
const openWithIronQc=openJob;openJob=function(id){openWithIronQc(id);const j=getJobs().find(x=>x.id===id),drawer=document.querySelector('#overlay-root .drawer');if(!j||!drawer||j.p.name!=='Iron Work')return;const checklist=(j.p.checklist||[]).map(c=>`<label class="iron-check-row"><input type="checkbox" data-iron-check="${id}" data-check-key="${c.key}" ${c.done?'checked':''}><span>${esc(c.label)}</span><small>${c.done?'Checked':'Pending'}</small></label>`).join('');drawer.querySelector('.qc-section')?.insertAdjacentHTML('afterend',`<section class="panel iron-qc-checklist"><div class="panel-header"><div><h2>Iron work QC checklist</h2><p>Record the checks listed on the iron-work job sheet.</p></div><span class="eyebrow">${(j.p.checklist||[]).filter(c=>c.done).length}/10</span></div>${checklist}<div class="field" style="margin-top:12px"><label>QC remarks</label><textarea data-iron-remarks="${id}" placeholder="Defects, rework or approval notes">${esc(j.p.qcRemarks||'')}</textarea></div></section>`)};
document.addEventListener('change',e=>{const box=e.target.closest('[data-iron-check]');if(!box)return;const j=getJobs().find(x=>x.id===box.dataset.ironCheck),c=j?.p.checklist?.find(x=>x.key===box.dataset.checkKey);if(!c)return;c.done=box.checked;c.by=currentActor();c.at=new Date().toISOString();addActivity(currentActor(),j.id,`${c.label}: ${c.done?'checked':'reopened'}`);localStorage.setItem(STORAGE_KEY,JSON.stringify(db));box.parentElement.querySelector('small').textContent=c.done?'Checked':'Pending';toast(`QC checklist updated: ${c.label}.`)});
document.addEventListener('input',e=>{const field=e.target.closest('[data-iron-remarks]');if(!field)return;const j=getJobs().find(x=>x.id===field.dataset.ironRemarks);if(j){j.p.qcRemarks=field.value;localStorage.setItem(STORAGE_KEY,JSON.stringify(db))}});
const jobWithLinePhotos=openJob;openJob=function(id){jobWithLinePhotos(id);const j=getJobs().find(x=>x.id===id),drawer=document.querySelector('#overlay-root .drawer');if(!j||!drawer||!j.o.items?.length)return;const cards=j.o.items.map((it,i)=>`<div class="job-product-photo-row">${it.photoData?`<img class="product-thumb" src="${it.photoData}" alt="${esc(it.name)}">`:'<span class="photo-placeholder">No photo yet</span>'}<div><strong>${esc(it.sku||'')} · ${esc(it.name)}</strong><small>${it.qty} units${it.dimensions?` · ${esc(it.dimensions)}`:''}</small></div><button class="compact-button" type="button" data-upload-line-photo="${j.o.id}" data-line-index="${i}">＋ ${it.photoData?'Replace':'Add'} photo</button><input class="photo-input" type="file" accept="image/*" data-line-photo-input="${j.o.id}" data-line-index="${i}" hidden></div>`).join('');drawer.querySelector('.detail-facts')?.insertAdjacentHTML('afterend',`<section class="panel job-product-photos"><div class="panel-header"><div><h2>Order products</h2><p>Reference photos and specifications for this job.</p></div></div>${cards}</section>`)};
